"use strict";

const STARTING_MODES=[
  {id:"easy",label:"Easy",start:GENESIS,desc:"Begin with Bitcoin's first block on 03 January 2009. You get the longest campaign and learn each mining era as it arrives."},
  {id:"medium",label:"Standard",start:START,desc:"Begin on 03 February 2009 with the original campaign timeline: early enough to grow from one laptop, without starting at block zero."},
  {id:"hard",label:"Hard",start:1359417600000,desc:"Begin on 29 January 2013 as specialised ASIC miners arrive. Your laptop is already outclassed, so upgrading quickly matters."},
  {id:"impossible",label:"Impossible",start:1735689600000,desc:"Begin on 01 January 2025 against an industrial network. You have less than 20 months of recorded history to build a viable operation."}
];
const BALANCE_SCENARIOS=[
  {name:"Genesis hobbyist",date:"2009-02-03",hardware:{laptop:1},facility:"home",region:"na",cash:1500,maxShare:.02},
  {name:"GPU garage",date:"2011-06-30",hardware:{gpurig:2},facility:"garage",region:"na",cash:10000,maxShare:.01},
  {name:"First ASIC shop",date:"2013-12-01",hardware:{avalon:10},facility:"workshop",region:"na",cash:100000,maxShare:.01},
  {name:"S9 operator",date:"2016-12-01",hardware:{s9:40},facility:"workshop",region:"iceland",cash:500000,maxShare:.01},
  {name:"Post-halving warehouse",date:"2020-12-01",hardware:{s19:200},facility:"warehouse",region:"texas",cash:5000000,maxShare:.005},
  {name:"Institutional campus",date:"2024-06-01",hardware:{s21:1500},facility:"campus",region:"texas",cash:30000000,maxShare:.005}
];
/* The one place the version is written. The header, the page title and the top changelog entry must all agree with it; a contract checks. */
/* The release label is "<stage> <version>": Beta 1.0. Everything that shows or sends it reads APP_RELEASE, so a stage change is one line. */
const APP_STAGE="Beta";
const APP_VERSION="1.2.3";
const APP_RELEASE=`${APP_STAGE} ${APP_VERSION}`;
const CHANGELOG=[
  {date:"2026-10-10",title:"Beta 1.2.3 hands-on tutorial, a real dice roll, clearer charts and cash at a glance",items:["The opening dice ceremony now feels like a roll: press and hold the die to shake it, harder the longer you hold, then let go and it tumbles and lands. You no longer pick the number; the browser's secure randomness decides each throw when you let go, and how long you shook it changes only the animation. Space or Enter works too, a quick tap still rolls, reduced-motion settings get a short flicker instead of the shake, and each result is read out to screen readers.","The first-run tutorial is now ten short, hands-on steps. Each one asks you to do one real thing in the game, highlights where to do it and moves on once it is done, so by the end your wallet is fully set up: online key backed up and stored off-site, a verified signer holding a backed-up reserve key, and somewhere for mining income to go. Back, Skip and a step counter are on every card, a reload resumes on the same step, existing saves are never forced into it, and the footer offers Replay tutorial. It can never leave you stuck: every card has a button that does its step, a delivery runs the clock by itself until it arrives, and doing things early, buying extras or undoing a step moves the card to the step that is now open and says why. The signer's price is set aside from your cash when the tutorial starts (the top bar shows it held) so nothing else you buy can leave you short; it pays for the signer, or comes back if you skip.","Every chart now uses one shared legend style, with swatches that match their lines, units, and alignment that fits the panel on wide and narrow screens. The Energy tab charts benefit most.","Cash available now sits in the top bar on every tab, so your liquid cash is in view while you browse miners or anything else.","The Energy tab tariff model no longer shows monthly bills vastly too large: a daily bill was being multiplied by the length of a month in milliseconds.","On phones the tariff model now fits the screen with F1–F4 in view instead of scrolling sideways, and the Bitcoin price chart's axis labels are readable instead of squashed to a few pixels.","On a 1280-wide screen the era name in the top bar stays on one line beside your cash, shortening when space is tight; the full name is in its tooltip.","Cache-busting version bumped so browsers fetch the new and changed files together."]},
  {date:"2026-10-10",title:"Beta 1.2.2 source citations",items:["The Coldcard seed-entropy and Ledger customer-data breach chapters now show their source links in the Bitcoin story, like every other chapter.","Cache-busting version bumped so browsers fetch the corrected files together."]},
  {date:"2026-10-10",title:"Beta 1.2.1 startup guidance and account security",items:["The opening now explains that Timechain is a sandbox for testing market timing, laptop-first mining, miner pricing, geopolitics and security rather than a promise of profit. It points out that a low-cost operation can pause and return to the market instead of carrying a fleet too early.","Market and Pools now model a mobile phone as an operation asset. Exchange and mining-pool accounts can use simple email 2FA toggles, with a later device-backed security upgrade that enables both accounts and reduces the recurring setup burden.","The launch renderer no longer declares its starting mode twice, and all browser assets use the 1.2.1 cache-busting version so an old cached script cannot prevent the game from booting."]},
  {date:"2026-10-10",title:"Beta 1.2 reserve recovery and clearer wallet language",items:["A cold-only operation that already carries arrears can now fetch enough of its reserve to clear both the old debt and the current bill. The settlement stays recoverable even after the grid is cut, with the signing delay and shortfall shown plainly.","The opening wallet lesson now says in ordinary language that a wallet does not store bitcoin: it finds the coins assigned to you and proves you may spend them."]},
  {date:"2026-10-10",title:"Beta 1.1 copy overhaul",items:["Custody now starts with online spending authority, the cold reserve, recorded recovery material and custodian-held balances. Vague posture labels are replaced by explicit game assessment labels, with findings and the assessment’s limits explained beside lending and theft cover.","claude1337 follows the operation through paid bills, pool mining, a cold reserve and the first ASIC owned. One-time fictional letters connect those choices into a continuing story, while bill-rescue copy carries the same thread into decisions.","Bill-rescue choices, trading and equipment confirmations now explain cash availability, timing, debt and the future income being given up. Hardware announcements connect hash rate and efficiency to competition and operating costs.","Custody explanations and action notifications now connect keys, signers, backups, multisig, verification and withdrawal permission to the risks they address. Loss popups describe risk reduction rather than guaranteed prevention, and the recovery lesson reflects the actual game rules.","The opening and first key lesson explain signatures, recovery and how trust changes across the campaign. Fictional claude1337 letters in the Ledger respond to missing online backups, incomplete recovery plans and backups sharing one location, and retain their status in the local save.","The dashboard now groups mining, treasury and progress around the questions each statistic answers. The next bill appears before historical charts, and operating cards lead with decisions.","The ticker separates your money, your operation and the Bitcoin network. Larger headings and readable explanations give numbers and supporting copy different visual roles.","Page introductions lead with the next move, with the operating trade-off below the stats. Expected mining output, indexed charts and the illustrative transaction queue explain their limits beside the visual."]},
  {date:"2026-10-10",title:"Beta 1.0 Timechain",items:["Hashrate is now Timechain: a game-first history of Bitcoin, from the Genesis Block to today, in which you mine, keep your keys safe and stay solvent as the technology, the network and the world change. The name moves with the game, which is about custody and risk as much as it is about hash rate. Saved runs carry over.","The coin at the top left is now a link to the Bitcoin whitepaper, in a new tab.","The version is now Beta 1.0, with the seed beside it in the header. The game is feature-complete for its first public release; from here changes are fixes and polish."]},
  {date:"2026-10-10",title:"Alpha 2.33 emergency stop stays stopped",items:["Emergency stop all now stays stopped. It stops every machine at once (no mining, and no electricity for the fleet; rent, internet, staff and insurance still fall due), but the next monthly bill used to switch the site back on by itself, with the electricity running again, because paying a bill restores power that unpaid arrears had cut and could not tell the two apart. A stop you chose is now only undone by Start site power, and clearing arrears does not undo it either. Stopping now says what it does, and the button explains itself when you hover it.","The header no longer says \"Operator campaign\" or \"Historical replay\": the seed now sits beside the version number, and the era name stays."]},
  {date:"2026-10-10",title:"Alpha 2.32 start on Standard",items:["A new run now defaults to the Standard start, 03 February 2009, instead of Easy on the day of the Genesis Block. Easy, Hard and Impossible are still a click away under Customise your run before you begin.","The first screen now frames that start the way it would really have happened: a month after the Genesis Block, with an IRC message from the friend who has read the mailing list and has views. Easy (the day of the Genesis Block) gets a short whisper from the same friend; Hard and Impossible, years on, get none."]},
  {date:"2026-10-10",title:"Alpha 2.31 cut the line, and a celebration",items:["You can now cut the internet. It is a plan in Facilities, \"No internet (cut the line)\": it costs nothing, nothing can mine on it, and the clock keeps running. It is how you put a run on hold: stop the machines (the laptop too), sell what is spare, cut the line, and wait for a date you have to guess, because without the line you have no idea what is happening in the world. Machines left switched on keep drawing power, and rent, staff and insurance still fall due.","While you are offline most of the game goes dark. The Dashboard becomes an offline summary, the Mine keeps the floor, servicing and cooling (the catalogue is locked), and the Ledger and Method stay open. Pools, Treasury, Facilities, Energy, Learn and Tech are locked, the ticker's outside numbers read NO LINK and the Bitcoin story goes quiet.","The major chapters of the story that fall while you are offline are held, and shown one at a time when you reconnect, with their skill points; their effects on your operation still happen on the day. New hardware announcements wait for you too.","Continuous trading arriving in July 2010, the moment the first months build towards, now always opens its window, with a milestone banner and a burst of confetti, whether or not story pauses are on. A finished run gets confetti over its score too (a run that ends in failure does not). Nothing for a browser set to reduce motion."]},
  {date:"2026-10-10",title:"Alpha 2.30 no market, no rescue",items:["A run now opens with $2,500 by default, up from $1,500. You can still choose as little as $1,500 for a harder start, in the Starting Liquidity control before you begin.","Before Bitcoin has a market price (July 2010) nothing you mine can be sold, so cash is the only way to pay a bill. There is no more restructuring or carrying arrears through that gap, which only deferred the same shortfall bill after bill. A bill that cash cannot meet is paid by selling miners at resale value, and if that is not enough either the scored campaign ends, with an end screen that says why. A campaign that starts after the market opens is unaffected.","Selling miners at a settlement now works on the machines you have installed, such as the quad-core tower, and not only on ones already retired to storage. The clock is stopped at a settlement, so there is no time to retire a machine first, and the button used to offer a sale of nothing.","The Dashboard warns you when your cash will not last until the market opens, the settlement screen says plainly which routes are closed and why, and the tour and Method (Start here) explain the rule."]},
  {date:"2026-10-10",title:"Alpha 2.29 every site its own place",items:["Every site after the Home office now has its own look in the 3D floor, instead of one slate grid floor at seven sizes. The Rented garage is whitewashed brick with oil on the floor, a pegboard of tools, an oil drum, tyres, a paint shelf and a frosted window. The Light industrial unit has breeze blocks with a blue dado, painted bay lines, fire points, a three-phase board with its conduit, a tea point and a bay of racking. The Mining warehouse has profiled cladding, high-bay racking full of stock and a painted pedestrian route. The Grid-scale campus is a clean data hall with wall panels, chilled-water supply and return pipes and a fire main. The Modular container yard has gravel and ruts, weathered containers in different colours and floodlight masts. The Hydro colocation plant has grass, the river and its rocks, and trees. The Sovereign megacampus has asphalt, a solar field and battery cabinets. The warehouse and the campus also close the rest of their outline with kerb-height walls on the front and right, a tall post at each corner and a gap for the loading door, so the building no longer looks half built while the floor stays in view.","The wall light and clock in the Home office no longer overlap."]},
  {date:"2026-10-10",title:"Alpha 2.28 a home office that looks like one",items:["The 3D floor for the Home office is no longer a small factory. It is a spare room: wooden floorboards and a rug, painted walls with skirting and cornice, a window with curtains where the steel vent used to be, a bookcase with books and archive boxes, a filing cabinet, a plant, pictures, a wall clock and a wall light, a consumer unit on the wall, and a desk corner with a toolbox where the service bay was. There are no hazard stripes, steel posts, strip lights or emergency stop, and anyone working there wears ordinary clothes, not hi-vis and a hard hat. Larger sites are unchanged."]},
  {date:"2026-10-10",title:"Alpha 2.27 see your order",items:["A machine you have ordered now shows where it is on its own card in the Hardware catalogue, at the top of the card where you pressed Buy: how many are on order and when they arrive, how many have been delivered and are waiting to be commissioned (with a button to commission them), and how many are still to rack. The Incoming fleet card above the catalogue still has the whole pipeline.","Toasts about racking and retiring machines no longer talk about a crew you may not have. With no technician on the payroll it is you doing the work, and they now say so; with technicians they name them."]},
  {date:"2026-10-10",title:"Alpha 2.26 the tech tree, readable",items:["Hovering a skill in the tech tree now always shows its detail on top, readable. Before, the skills drawn after it in the page painted over it, so their names and costs showed through the text; the skill you are pointing at is now lifted above its neighbours. The detail also opens upward or to the left when the tree would otherwise cut it off, and its text is a little larger and lighter.","The Lightning tip at the bottom of the page is left-aligned with the rest of the footer."]},
  {date:"2026-10-09",title:"Alpha 2.25 a glimpse of what is next",items:["Facilities now shows the next site and the next location, greyed out, with the date each unlocks and how far off that is, from the first day of a run. The Hardware catalogue in Mine does the same for the next machine. Only the very next step is shown, so a player who has hit a ceiling can see when the next tier arrives, and nothing further is spoiled.","The Lightning tip link has moved to its own line at the very bottom of the page."]},
  {date:"2026-10-09",title:"Alpha 2.24 cold storage from day one, and disasters you can see",items:["Cold storage is now possible from the first day. The first signer is an old late-1990s PC from the basement: free, a day to dig out, and there is only the one. It never goes online, the key is made on it, and anything it signs travels by USB stick. If a fire takes it, anyone who can use a screwdriver can put another together from spare parts: also free and also a day, and your key can be restored onto it from its backup. Hardware wallets still arrive from 2014.","The Custody section has a Set up cold storage card at the top that names the five steps (get a signer, make a key on it, write it down, put it in your wallet, move coins in) and puts the button for the next one on its own line. Coins can no longer be moved to a wallet nobody can sign for, from the page, the lab or a payout, and the buttons say why.","The page itself is in five numbered groups: your coins, equipment and backups, spending and standing, verification, and learning. The tour has two more steps on custody, and the Dashboard briefing nudges you to set up cold storage once coins have arrived.","Nothing in the online wallet can be lost, stolen or burnt in the first sixty days of a campaign, so a new run no longer ends its first month on a roll the player could not have answered. After that the chances are as before.","When a custody incident costs you coins, the window now says how likely it was: the chance in the month it happened, what that adds up to over a year, and what would have lowered it, so a rare piece of early bad luck reads as bad luck and an avoidable one reads as a lesson.","About 40% more recorded data is bundled: the median and 90th-percentile fee rate of every day since 2009, the height of every difficulty retarget, and the four halving blocks. A payment from 2017 and a cold-storage sweep from any year now cost what a byte really cost that day, and rushing a signing pays that day's queue-jumping premium instead of a flat three times.","Disasters now look like something. The loss window opens with an emblem for what happened (a flame, a flood, a broken padlock, a failed disk, a compromised key) and a tinted top bar. After a fire, a flood or a break-in at the mine the live floor wears it for three weeks: scorch and a flame with smoke drifting up over the machines, standing water, or police tape across the picture, with a line saying what it was and for how long. A grid outage plunges the floor into darkness and an internet outage dims it. It is a picture only: no number changes and every button still works.","The footer has a Lightning tip link, for anyone who wants to say thanks, and an Email link for anyone with feedback who would rather not use GitHub."]},
  {date:"2026-10-09",title:"Alpha 2.23 ready for other people",items:["A save the game cannot read is now set aside instead of replacing it: the raw text is kept in your browser, the game says so, and Export unreadable save in the footer gives it to you. If the game cannot start at all you now get a recovery page, not a blank one, with Export my save, Start a new run (which keeps the old save aside) and Try again.","If your browser refuses to store the game (a private window, blocked site data, a full disk) the header now says NOT SAVING and the game tells you once, so you know to use Export save.","The tab pauses the game when you switch away from it, and says so when you come back. It used to keep running and fast-forward, so you could return to a bill you had not seen arrive.","The tour really does hold the clock now: the speed buttons tell you so rather than starting it, and a bill that falls due during the tour takes the screen until you have dealt with it. Good-news notices wait behind a window instead of covering it.","The key the opening ceremony makes now comes from your browser's own randomness whichever way you make it. 'Generate the key for me' used to draw from the run's seed, which the header shows, and the ceremony called the key harmless: it is for this game only, but it is stored unencrypted in your browser and must never hold real bitcoin. Both are fixed, and the warning is now readable text.","The footer has Report a bug and Suggest something (each opens a pre-filled GitHub form with your version and date), Copy debug info, and a plain statement of what is stored: no accounts, no tracking, no analytics, and nothing leaves your browser. The smallest notes and the footer are larger and clearer, and a shared link now has a preview image.","Keyboard focus now stays on the control you were using when the page repaints, and an open window takes focus so Tab works inside it. Secondary text is lighter and the smallest labels are bigger. A mistyped address gets a proper 404 page with a way back.","Two dates were corrected: the fourth halving falls on 20 April 2024 (the day block 840,000 was mined, in UTC), and r/Bitcoin opens on 9 September 2010."]},
  {date:"2026-10-08",title:"Alpha 2.22 a tour of every room",items:["A new run now begins with a guided tour, with the clock stopped. It opens each area in turn (the clock, your numbers, your briefing, the history, Mine, Pools, the Treasury and its three sections, Facilities, Energy, Learn, Tech, the Ledger and the Method), rings the part that matters and says what it is for and what you can do there.","You can step back, skip it, or use the arrow keys and Escape; it picks up where it left off if you close the page; the clock goes back to the speed it had when you finish. Take it again from Tour in the footer whenever the page stops making sense. Saves from before it are not walked through it, and on a phone it sits at the bottom of the screen and skips the stop for the number strip, which a phone does not show."]},
  {date:"2026-10-08",title:"Alpha 2.21 the first key is a real key",items:["The key the opening ceremony makes is now a real software key, the one behind your online wallet. It lives on the mining computer at the mine, so a fire, a flood or a break-in takes it, a seized or stolen backup is a stolen key, and the disk can fail on any month. With a backup somewhere the mine cannot reach, a lost computer costs an afternoon and a fee; without one, the coins in the online wallet were the file.","The ceremony now ends by offering to write the key down, and the Custody section has a card for your online wallet: where the key lives, whether anything else holds it, and what the computer failing costs. An online wallet with coins and no backup is a finding that keeps your custody from a strong posture. The key is never part of a wallet policy. Runs and saves from before this have no first key and behave exactly as they did."]},
  {date:"2026-10-08",title:"Alpha 2.20 a run starts with a wallet",items:["Beginning a run now takes you through the first-wallet ceremony instead of skipping it behind your back: roll dice for entropy, or let the game generate the key. The clock does not start until the wallet exists, because a block pays to an address and an address comes from a key. Old saves are untouched.","The Method is brought up to date with everything since 2.11: how far away the reserve is and what fetching it costs, what a payment costs on a given date, where pool payouts land, bank-box seizure, named lenders and partial repayment, rushing a rotation and wiping a retired signer, and the removal of the automatic sale. The version is now written in one place."]},
  {date:"2026-10-08",title:"Alpha 2.19 fees, lenders and loose ends",items:["A payment now costs what the date charged: before 2017 the fixed fee wallets paid, then the fee market, so December 2017 is several times dearer than before and a quiet 2025 payout a small fraction of it. Low payout thresholds are now a real decision in a fee spike.","A pledge goes to a named lender, picked for you. Celsius, Voyager and BlockFi each stop paying out on their real dates in 2022; Nexo and Ledn do not. Only the one that failed takes your coins, and a loan with a quorum never has one to lose.","You can repay a quarter, half or all of a loan against your coins, and the same share of the coins comes back. A bank box can now be opened by a government: a ban on mining in Sichuan can take what is in it. A retired key's signer can be wiped and used again, and a key rotation can be rushed."]},
  {date:"2026-10-08",title:"Alpha 2.18 one Treasury",items:["Market, Custody and Finance are now sections of one Treasury tab, with a strip above them that is the same on all three: what you can spend today and for how many days of bills, your hot wallet, how far away your reserve is and how many coins it is made of, your custody posture, and when the next bill lands, with whether the reserve can meet it.","Every notice that used to point at Market, Custody or Finance still opens the right section. The section bar stays under the header as you scroll, on a phone as well, and the dashboard's custody card now reads your keys, not just how much you hold yourself. The payout destination card says what a reserve of many small payouts will cost to spend."]},
  {date:"2026-10-08",title:"Alpha 2.17 loans and cover, measured",items:["Coin cover was repriced to a few multiples of what it can be expected to pay instead of dozens, a loan can be taken at 80, 60 or 40% of what the coins allow (60% by default, and 60% when a bill is the reason), and a loan now warns you five points before it is called.","Restoring a key from its backup takes the days the backup takes to fetch: two from a bank box or a trusted person's house, one from home, none at the mine. Net worth now subtracts the operating loan as well as the loan against coins, so borrowing no longer makes you richer."]},
  {date:"2026-10-07",title:"Alpha 2.16 your keys have a price",items:["Your custody now has a posture that a lender or an insurer can read: none, basic, strong or audited, each rung blocked by a named finding. Your security officer can commission an audit ($4,000, fourteen days) that reports every finding and, if it passes, certifies the wallet for a year.","Coin cover, from 2016, pays a share of a theft in cash, more and cheaper the better your posture. It will not pay for a seed you knew was flawed, a seed you typed into a fake, or a key you knew somebody else held and had not replaced, and it does not pay in its first thirty days.","From mid-2018 you can borrow against your coins without selling them: in collaborative custody the lender holds one key of your 2-of-3 and the coins stay out of its reach, or you can pledge hot coins to a lender at once for less and at more cost. A fall in the price calls the loan, two weeks later the lender sells, and a lender that fails takes a pledge and leaves the debt. Both can pay a settlement. The Market now says what depositing from your reserve costs."]},
  {date:"2026-10-07",title:"Alpha 2.15 a key is a person's secret",items:["A key can now be held by you, the treasury manager, a field technician or a new security officer. Dismissing the person who held it does not remove the key from the wallet: it makes it known to someone who no longer works for you, and every key they ever knew is exposed, even one handed back.","An exposed key stays usable, and the danger is the clock: if the exposed keys alone satisfy the wallet, the chance somebody sweeps it rises every day. Half of those who learn a key mean to use it within weeks; the rest wait at least three months and then their chance climbs too, and you are never told which. One exposed key of a 2-of-3 is harmless; in single signature it is the whole wallet. A security officer halves the chance.","Replacing a key is a rotation: a new key on a spare signer, every coin swept to the new wallet at the real fee for the weight of the coins, days during which the wallet cannot be spent from, and a quorum's descriptor to be written down again. It consolidates your coins into one. The staff card warns you before you dismiss somebody who knows a key."]},
  {date:"2026-10-07",title:"Alpha 2.14 your keys have an address",items:["Every signer, seed backup and copy of the wallet configuration is now kept somewhere: the mine, home, a bank deposit box or a trusted person's house. New things start at the mine, so the first lesson is the one real people learn the hard way: a backup in the same drawer as the signer is one point of failure.","Each place has a monthly chance of a fire, a flood and a break-in, and a distance: a key in a bank box is a trip away and the days are added to every signing. Fire and flood take signers and paper and steel survives; a break-in takes steel too, and a stolen seed is a seed somebody else holds. If every copy of what a wallet needs was in the place that burned, the coins are stranded.","Signers can be restored onto new devices from a surviving backup, which takes the days that backup's place takes to fetch it from (a bank box is two days, the mine none), the wallet configuration can be copied to a second place, and moving anything takes days during which it cannot sign. Anything kept at the mine goes with the fleet when it moves region, and a border can stop it."]},
  {date:"2026-10-07",title:"Alpha 2.13 custody joins the monthly bill",items:["If your reserve is in cold storage, the settlement decision now says how many days away it is and can fetch it: the bill is carried into the grace month so the clock runs while the coins are signed out, and they land in time to sell and clear the arrears. A rush pays three times the fee to skip the slow steps, but two keys kept apart can never arrive together.","Leaving cold storage is now priced by the weight of the coins it gathers at the going rate for that day, so every payout sent straight to cold is another coin to gather later and a December 2017 sweep costs far more than a 2019 one. A cold spend is reviewed before it starts and coins in flight are counted in your net worth."]},
  {date:"2026-10-07",title:"Alpha 2.12 nothing sells for you, and the floor holds",items:["Nothing is sold for you any more: a bill your cash cannot meet stops the clock and you raise the money yourself, usually by selling BTC at the Market. Missing a bill carries it into a grace month as arrears; a second miss cuts the grid.","The 3D floor no longer drops to the flat floor for good on a lost graphics context: it is rebuilt, tells you what happened for ten seconds, and only gives up after repeated failures. The mempool card keeps a fixed height and the phone header stays put while you scroll. History now runs to 6 October 2026."]},
  {date:"2026-08-21",title:"Alpha 2.11 accuracy pass: schemes, provenance and honest damping",items:["Method now states how heavily the early years are damped and by how much: competition is scaled 60x in 2009 tapering to 1x from 2014, which is a 0.02x effect on 2009 yield and 0.99x from 2024, and the tab shows the live factor for your own fleet and date.","Said plainly that the ASIC era runs the real block-probability arithmetic and the CPU and GPU eras do not, and that this is a balance decision rather than a historical claim.","Solo mining no longer says shares submitted, because solo against your own node submits nothing anywhere; it now reads difficulty-1 shares found, and shares submitted only when pool mining.","Your best share is now reconciled with the blocks you actually found: solo, it crosses network difficulty on exactly the days you find a block and never on the days you do not.","Pool payout schemes are now modelled rather than assumed, and carry dated timelines rather than one fixed method, because schemes were invented at particular moments and pools migrated between them.","Proportional came first, Slush ran its time-weighted score from November 2010 until moving to FPPS on 12 December 2023, PPLNS and PPS followed around 2011-12, FPPS arrived once transaction fees were worth passing on in 2014-15, ViaBTC invented PPS+ in August 2016 and OCEAN brought TIDES in November 2023.","A regression check now refuses to let any pool run a payout scheme before that scheme existed.","Poolin is marked as closed from 10 July 2026.","Pool fees corrected to real headline rates - AntPool 4%, F2Pool 2.5%, Deepbit 3% PPS, ViaBTC 2% PPS+, Slush 2%, BTC.com 1.5%, Foundry and MARA and OCEAN 0%.","A pay-per-share pool now costs more than its fee suggests: at mid-2023 fee levels a 3% PPS pool lands 9.8% behind the best option, because the transaction fees never reach you.","Fixed the Pools tab charging the pool fee twice in its expected-net-BTC figure.","Selecting a pool you are not eligible for no longer mines solo in silence while the tab still says pool; it fails over explicitly and says why.","Method now shows where every recorded series comes from, read live from the data bundle: the source, the through-date, the row counts and how each series was derived.","Documented that your own hash rate does move your odds through the share formula - below about 1% of the network doubling your fleet doubles your blocks, and at 2.5% share per-machine yield is 12% lower.","Corrected the claim that no BTC/USD price existed before Mt. Gox: New Liberty Standard quoted a rate from October 2009 and bitcoinmarket.com ran from March 2010.","Split the simulation engine into operator, maintenance, pools and notification modules so it fits inside the project's own module-size limit."]},
  {date:"2026-08-21",title:"Alpha 2.11 steadier repaints and manual intervention",items:["The Mine tab no longer kicks the page down when a fault notification arrives: the rebuild and its enhancement now happen in one task, so the browser never paints the short un-enhanced tab first.","Repaints now anchor on the card you are actually reading, keyed to its heading, so a fault row or the bench panel appearing above your position no longer shifts everything under you.","Ordering spare parts patches the Mine tab instead of rebuilding the whole page, which is what jumped the view down to miner selection.","High speeds now repaint less often rather than more - every 600ms at 16x instead of 300ms - and every queued repaint is aligned to the display refresh, which removes the jitter.","The bad-event screen shake is throttled to once every four seconds; the red flash still fires each time, so a burst of faults no longer throws the page around.","When every field technician is already committed to another repair, the next job now falls to you to complete by hand rather than being refused, provided the parts are in stock.","A self-serviced job no longer consumes technician capacity, so your own bench and a full crew can work in parallel.","The Mine floor bench panel now appears whenever no technician is free, not only when none are hired."]},
  {date:"2026-08-21",title:"Alpha 2.11 operator XP, levels and the best share",items:["Added a permanent operator experience bar to the header, with the running level, XP to the next level and your best share difficulty.","XP is earned from shares submitted, new best-share difficulty records, machines commissioned and repairs completed, with a 50% bonus on repairs you carry out yourself.","Share XP is logarithmic in hash rate, so a 2009 laptop earns roughly 8 XP a day and a 324 PH/s campus roughly 51 - a six-fold spread across eleven orders of magnitude of fleet size.","Your best share difficulty is now tracked and announced when you beat it by a wide margin: the number solo miners actually watch, drawn from a heavy-tailed distribution so it climbs in rare jumps.","Levels need 60 x (N-1) squared cumulative XP and grant skill points on a decelerating schedule - every level to 6, then every second to 20, then every fourth - about 22 points across a long campaign.","Peak operator level now contributes up to 60 mastery points to the Operator Score, taken out of the era-performance allocation, which drops from 800 to 740 so the total stays at 1,000.","XP augments the Operator Score rather than replacing it: XP only ever rises, so the Score keeps its era weighting and its penalties for bridge loans and receivership.","The Operator Score card now shows your level, mastery points, best share, shares submitted and a breakdown of XP by source.","On narrow screens the XP bar becomes a hairline progress strip along the bottom of the header instead of competing for width."]},
  {date:"2026-08-21",title:"Alpha 2.11 self-sufficiency: free labour, bench skills & dismissals",items:["Servicing your own fleet no longer costs fiat labour - a self-serviced job charges you for parts and nothing else. Technician crews are still paid.","Fumbling your own repair can now damage the machine: a wrong bolt, a mismatched connector pair or an over-torque past spec can cost several points of condition and sometimes break a second part outright.","That damage risk falls sharply with practice on that specific hardware type, from roughly 40% on a machine you have never opened down to a 2% floor.","Added Bench repair skills: cuts the chance of damaging a machine you are working on to 40% of its value.","Added Parts sourcing: every spare part costs 20% less.","Added Supply-chain contacts: spare-part orders arrive 40% sooner, supply shock included.","Added Practised hands: a familiar repair can complete itself with no puzzle at all, from 20% after one repair of that type up to a capped 85% after eight.","None of the four self-help skills require a facility tier, so a solo operator can stay self-sufficient instead of being pushed into hiring.","A new bench panel on the Mine floor shows completed repairs, current damage risk and auto-finish odds for every hardware type you own.","Staff can now be dismissed: salary stops immediately and one month's notice is added to that month's accrued bill.","A technician committed to a running repair cannot be dismissed until that job clears, and losing your last technician switches auto-repair back off."]},
  {date:"2026-08-21",title:"Alpha 2.11 exposure warnings, per-site floors & hands-on servicing",items:["Four historical collapses now warn you in advance, but only while you are actually exposed: Mt. Gox halting bitcoin withdrawals on 07 Feb 2014, a bank freezing QuadrigaCX's processor funds on 09 Oct 2018, the leaked Alameda balance sheet on 02 Nov 2022, and Beijing naming Bitcoin mining on 21 May 2021.","Each warning fires a one-time amber toast and ledger entry, then holds a banner showing the exact exposed balance or region until you withdraw, relocate, or the real event arrives.","Bitfinex's 2016 hack and Kazakhstan's 2022 internet shutdown are deliberately excluded because neither had a genuine public advance warning, and ignoring a warning leaves the real event's effect completely unchanged.","You now service your own fleet by hand until field technicians are hired: the Work-stage repair puzzle belongs to jobs you run yourself, and a hired crew completes its own work without handing it back to you.","Repair-puzzle state is now prepared when the job is created, so the puzzle can no longer appear with controls that do nothing until the clock advances.","Fixed a repair loop where a replaced part immediately re-faulted: a completed part swap now clears that part's fault count outright and restores condition above the 65% offline threshold with headroom against the same tick's wear.","Spare parts split from five shared items into nine era-scaled ones - a $15 laptop fan, $45 120mm case fan and $55 ASIC blower, plus $180 early, $480 mid-generation and $900 high-density hashboards chosen by each machine's era and release date.","Every facility tier now has its own mining-floor illustration, from a domestic spare room and a garage roller shutter through three-phase trade units, warehouse containment and substations to container yards, hydro penstocks and transmission switchyards.","All nine spare parts now have their own drawings instead of sharing five, so a laptop blower, a case fan and an industrial ASIC blower are told apart at a glance.","The Bitcoin Faucet popup now patches the page like a toast instead of forcing a full re-render, removing the scroll jump it caused.","The solo ledger label now reads Block reward (today) because the logged amount is the day's total, not one block's subsidy.","The Dashboard mempool visualisation now pauses with the simulation instead of animating while the clock is stopped.","The first skill point now arrives at 5 knowledge instead of 9, with later points still every 3.","Moved facility and spare-part illustration into its own module to keep the fleet view inside the agreed file-size ceiling."]},
  {date:"2026-08-18",title:"Alpha 2.10 fleet labour, exchange trading & risk",items:["Repairs now move through six labour stages - power down, disconnect, work, reconnect, fit & rack, stability check - each with its own complication chance, reduced by the new Field service technique skill.","Outside contractors now cover only one job at a time fleet-wide when no technician is on payroll; a second attempt is blocked until that job clears.","An unrepaired, unattended fault has a small daily chance to spread to a second part instead of sitting inert.","Added an overdrive toggle: +15% hash and +25% power draw at the cost of sharply higher wear and fault risk, able to push a facility over its own electrical capacity.","Surfaced the previously invisible load-based power-rate penalty on the Energy tariff desk and Mine's electrical capacity tile.","The forced BTC settlement rescue no longer executes a one-click sale: it routes to Market, where covering the shortfall means depositing to a real exchange and selling there, with the settlement clearing itself once cash covers it.","Redesigned every exchange into a trade ticket: a bid/ask quote, a branded monogram, and independent buy/sell sizing instead of one shared percentage slider.","Fixed the dashboard's displayed network hashrate to match the effective competitive figure mining odds are actually computed against, instead of the sparse raw recorded curve.","Bad events (faults, outages, compromises, migration incidents, settlement shortfalls) now trigger a brief red screen flash and shake.","Reduced the starter region's internet bill from $75/mo to $25/mo."]},
  {date:"2026-08-16",title:"Alpha 2.9 stabilisation & modular rebuild",items:["Replaced arbitrary opening liquidity with Hard, Medium, Easy and Very easy campaign modes.","Transaction displays now preserve tiny non-zero amounts and expose invalid quotes instead of presenting them as zero.","The Mine tab now uses one dollar-purchase button per miner, with unique batch quantities selected beside it.","Separated static data, simulation, actions, tab views, enhancements, rendering, events and styling into bounded files with structural regression checks.","Expanded the Method tab with opening-mode, quote-sizing, procurement, settlement and Operator Score mechanics."]},
  {date:"2026-08-15",title:"Alpha 2.9 ASIC release intelligence",items:["Every ASIC and hydro-ASIC release now pauses the timeline with a decision briefing containing physical hashrate, input power and joules per terahash.","Release alerts quantify the step change from the prior mining generation: throughput multiple, efficiency gain, equal-hash power demand and monthly energy-cost impact at the active site tariff.","A 1,000-machine flexible-load scenario translates each generation into megawatts, monthly energy and one-hour demand-response potential.","The Mine tab now retains an ASIC efficiency and controllable-load timeline so generation changes can be compared after their launch alerts are dismissed."]},
  {date:"2026-08-15",title:"Alpha 2.8 transaction confirmations",items:["Added an explicit review modal before market, ETF, Strategy security, miner and fleet-liquidation purchases or sales can execute.","Every confirmation freezes the simulation quote and places the asset or hardware given beside the cash, BTC, shares or equipment received.","Percentage basis, reference or unit price, fees and resulting balances are shown before commitment; cancelling restores the prior timeline speed without changing state.","Confirmation uses the same underlying calculations as execution so the review and completed transaction remain aligned."]},
  {date:"2026-08-15",title:"Alpha 2.7 configurable capital & precise orders",items:["Added a pre-run liquidity control from $1,500 to $250,000, with a broad slider and exact numeric override.","Every market venue now has a persistent 1–100% transaction-size control with slider, exact percentage entry and 1%, 25%, 50% and 100% snaps.","Deposit, withdraw, buy and sell are now separate confirmation buttons that use the displayed percentage and state clearly which source balance it applies to.","Opening liquidity and percentage-sized transactions are captured by the permanent activity ledger."]},
  {date:"2026-08-15",title:"Alpha 2.6 activity ledger & fleet liquidity",items:["Added a permanent, filterable transaction and action history with post-action cash, self-held BTC, fleet hash and market-price snapshots.","Existing saves migrate their retained recent log; all new trades, rewards, bills, fleet changes, custody moves and operational decisions remain in the ledger.","Added a bill-aware fleet liquidation desk that previews the exact miners and proceeds needed to reach a chosen fiat target while protecting stronger hash margin first.","Monthly settlement rescue now identifies the specific fleet sale and expected cash proceeds before the player commits."]},
  {date:"2026-08-15",title:"Alpha 2.5 recorded network economics",items:["Replaced 118 price anchors with 5,870 daily BTC/USD observations while retaining the pre-market discovery points.","Mining yield now follows 920 daily difficulty states reconstructed from recorded hashrate and block count instead of inferring difficulty from quarterly interpolation.","Transaction fees now use a seven-day network mean across 1,009 anchors, replacing five flat fee eras and exposing real fee-market cycles in profitability.","Network hashrate, transaction activity and block height now use smoothed or cumulative recorded series, with their measurement windows labelled in the live dashboard."]},
  {date:"2026-08-15",title:"Alpha 2.4 obligations & connectivity",items:["Added a rolling three-settlement obligations timeline with an itemized forecast for energy, rent, internet, payroll, insurance, node services and finance interest.","Internet is now a real jurisdiction-priced operating cost with local fixed broadband, dual-SIM cellular failover and business fibre/SLA choices.","Connectivity plans trade monthly cost and outage resilience against mining propagation performance, while facility scale increases bandwidth costs.","Rebalanced the technology tree with escalating point costs, historical dates, facility prerequisites and smaller early multipliers."]},
  {date:"2026-08-15",title:"Alpha 2.3 game-first economy",items:["Replaced the passive BTC leaderboard with a 1,000-point Operator Score built from solvency, profitability, uptime, competitiveness, milestones, custody and resilience.","Added treasury policies that can HODL, sell a chosen share of monthly mining production or automatically sell only enough BTC to cover settlement.","Monthly shortfalls now pause the clock for an explicit rescue decision: sell self-held BTC, liquidate inefficient miners, use costly bridge finance or enter receivership.","Repeated receivership can end the scored campaign, preventing an insolvent offline fleet from coasting to victory while preserving sandbox continuation.","Growth finance can now be supported by recent mining revenue as well as fiat collateral, allowing a profitable operator to fund the next hardware generation."]},
  {date:"2026-08-09",title:"Clearer finance and energy ownership",items:["Removed power-contract selection from the shared operating-strategy card, leaving tariff decisions exclusively in the Energy tab.","Project finance now appears as unavailable until industrial mining credit emerges in 2014, then calculates remaining capacity strictly from eligible unborrowed fiat.","Unavailable growth funding is visibly disabled and displays the exact time or collateral requirement instead of relying on a clickable button and follow-up toast.","Financing exposure now reports true eligible collateral and remaining borrowing capacity, including a genuine zero balance rather than a display-only floor."]},
  {date:"2026-08-09",title:"Detailed American flag artwork",items:["Rebuilt the North America flag SVG with thirteen alternating red and white stripes instead of a blue field with red bars.","Added a compact fifty-dot white star field to the blue canton so the flag remains recognizable at both facility-card and header sizes."]},
  {date:"2026-08-09",title:"Node catch-up and geographic redundancy",items:["Full nodes now accumulate a modelled block backlog while they are powered down, disconnected or short of storage, then visibly catch up before returning to the chain tip.","Laptop, dedicated and hardened deployments synchronize at different rates, teaching that a node can be running without yet being current.","A geographically independent backup node becomes available in 2018, performs its own initial synchronization and can preserve verification during a primary-site power, policy or connectivity failure.","Primary and backup nodes now expose separate sync state, failure reasons, verification paths and operating overhead; remote redundancy protects validation continuity but does not provide local block-template, relay or Lightning services."]},
  {date:"2026-08-09",title:"Laptop-first full-node progression",items:["Bitcoin Core now begins on the Basic laptop as an archival full node instead of incorrectly presenting the starting wallet as SPV-only.","Laptop verification follows the mining laptop's power and hardware state; a dedicated full node remains online when miners are deliberately shut down, while site outages, arrears and insufficient storage still matter.","Reframed the paid node purchase as a dedicated full-node appliance, retained the hardened relay tier and added live verification coverage, continuity and offline-reason UX.","Laptop nodes can switch between archival and pruned profiles, while Lightning still requires a continuously operated dedicated node."]},
  {date:"2026-08-09",title:"Complete fleet artwork and clear status lights",items:["The permanent Basic laptop now receives its hardware SVG in the Mine catalogue, matching every purchasable miner card.","Fleet-header quantity badges moved to the upper-left so they no longer cover the upper-right hardware-status indicator.","Reduced the solid green online light diameter by one-third for a cleaner status treatment."]},
  {date:"2026-08-09",title:"Bitcoin favicon",items:["Added a dedicated Bitcoin-orange browser favicon with a white ₿ mark for tabs, bookmarks and installed shortcuts."]},
  {date:"2026-08-09",title:"Earned cash-reserve milestone",items:["The Six-month cash reserve milestone no longer triggers from the tiny home-office bill against untouched starting cash.","Qualification now requires a tier 2 facility or larger, 180 actual mining-uptime days, no grid arrears and six months of unborrowed fiat against full operating and project-finance costs.","Finance now shows the next unmet reserve requirement so the milestone is demanding but legible."]},
  {date:"2026-08-09",title:"Alpha 2.2 balance and profitability desk",items:["Added a live Mine profitability desk showing marginal BTC and fiat revenue, energy cost, hash margin, production cost, payback and site-capacity use for each available miner.","The desk distinguishes owned fleets from one-unit purchase candidates and flags hardware whose shutdown would improve cash margin.","Added six deterministic era benchmark scenarios to the Method tab so network share, capacity, runway and solvency assumptions can be regression-checked as the game evolves.","Aligned heat-reuse savings with the daily bill ledger so the Mine desk, monthly forecast and actual settlement use the same energy calculation."]},
  {date:"2026-08-09",title:"Realistic network competition",items:["Early mining payouts now include a modelled population of unseen hobbyists around the sparse historical hashrate estimates.","The rest of the network responds as the player's fleet scales, preventing one operation from unrealistically reaching dominant global share.","Dashboard share and payout calculations now use the same effective-competition model while the header retains the stored historical hashrate baseline."]},
  {date:"2026-08-09",title:"Live Mine desk",items:["Opening Mine no longer pauses the historical timeline or changes the selected simulation speed.","Miner prices and buy-max limits refresh while the Mine tab remains open.","Hardware purchases, sales and activations now redraw only the Mine content and live header instead of rebuilding the entire game screen."]},
  {date:"2026-08-09",title:"Clear compact miner pricing",items:["Miner purchase and resale controls now show total transaction values instead of presenting an unexplained machine count in parentheses.","Large fiat and bitcoin amounts use consistent lowercase k, m, b and t suffixes.","Buy-max labels now state both the compact total price and the number of miners, with BTC maximums also respecting remaining facility capacity."]},
  {date:"2026-08-09",title:"Facility-gated staffing",items:["Staff recruitment now requires a tier 3 Light industrial unit or any larger facility.","Finance explains the facility requirement and keeps every hire action disabled until it is met.","Existing employees remain on payroll if an established operation later relocates to a smaller site."]},
  {date:"2026-08-09",title:"ETF chronology and the Winklevoss arc",items:["Finance now keeps spot Bitcoin ETF exposure completely hidden until the U.S. products launch on 10 January 2024.","Added the SEC's 10 March 2017 rejection of the Winklevoss Bitcoin Trust to the historical story.","Added the Winklevoss Capital purchase of a 45% stake in Real Bedford FC after the deal was finalised in February 2025."]},
  {date:"2026-08-09",title:"Miner delivery, activation and status art",items:["Delivered miners now enter staged inventory and require explicit activation in Mine before they hash.","Miner artwork now shows green online lights, yellow electrical warnings, red hardware-fault flames and configuration warnings.","Corrected the quad-core tower artwork and enlarged the glowing fleet illustrations in the Mine header."]},
  {date:"2026-08-09",title:"Live learning progress",items:["Learning day and percentage counters now update on every simulation tick while the Learn tab is open.","Completion immediately refreshes the Learn view so knowledge checks and completed states appear without changing tabs."]},
  {date:"2026-08-09",title:"Progressive historical narrative",items:["Added era-aware narrative copy across every operating tab.","The framing now follows Bitcoin from an unknown hobby project through market discovery, industrialisation, sovereign stress and institutional adoption.","Late-game copy presents Bitcoin as a scarce, permissionless escape valve from fiat and counterparty risk without treating that thesis as guaranteed." ]},
  {date:"2026-08-09",title:"Nodes, templates and audit trail",items:["Added OCEAN and miner-selected block-template technology.","Added pruned, archival and mining-relay node profiles with power, bandwidth, connectivity and mining effects.","Established this permanent collapsed changelog in the Method tab."]},
  {date:"2026-08-09",title:"Historical data calibration",items:["Stored 118 Coin Metrics BTC/USD observations directly in the offline game.","Expanded network hashrate to 69 stored anchors and calibrated recent pool shares from mempool.space.","Added MARA Pool, Luxor, OCEAN and SpiderPool to recent pool history."]},
  {date:"2026-08-09",title:"Progression, finance and energy",items:["Added the Bitcoin whitepaper as the first learning activity.","Future content stays hidden until its announcement window.","Changed project finance to fiat-only collateral and strengthened energy, utilisation and contract trade-offs."]}
];

